local UIFishPoolStoreBackPackGoodsInfoNode = Class("UIFishPoolStoreBackPackGoodsInfoNode")
function UIFishPoolStoreBackPackGoodsInfoNode:__init() 
    self._goodsId = 0
    self._isEquip = false              --是否装备
    self._cb = nil
end

function UIFishPoolStoreBackPackGoodsInfoNode:__delete()
    self._goodsId = nil
    self._isEquip = nil              --是否装备
    self._cb = nil
end

