end

function UIFishPoolStoreBackPackGoodsInfoNode:Start()
    --SetButtonAction(self.BtnDetails, Bind(self, self.OnBtnTips))
    self.__everythingChangeHandler = Events.AddListener(Constants.EventNames.EveryThingChangeEventName, Bind(self, self.__ChangeCurrencyNum))
