function UIFishPoolStoreBackPackGoodsInfoNode:__ChangeCurrencyNum()
    if checkNumber(self._goodsId) == 0 then
        return
    end
    self:FillSelf(true)
end

function UIFishPoolStoreBackPackGoodsInfoNode:Refresh(goodsId, isEquip, cb, placeId)
    if not goodsId then
        return
    end
    self._goodsId = goodsId
    self._isEquip = isEquip
    self._placeId = placeId

    self._cb = cb
    self:FillSelf()
end

function UIFishPoolStoreBackPackGoodsInfoNode:FillSelf(isEvent)
    CfUtils.FillText(self.TexTrestrict, FishingUtils.GetFishGoodsLimitPlaceDesc(self._goodsId))
    local numText = FishingUtils.GetFishingGoodsShowNumText(self._goodsId)

    local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(self._goodsId)
    if vo then
        CfUtils.FillText(self.TextName, vo.name)

        local str = vo.description
        CfUtils.FillText(self.Text, str)
        CfUtils.FillText(self.TextDesc, vo.desc)

        CfUtils.FillText(self.TextNumber, numText)
        CfUtils.FillImage(self.ImgIcon, vo.photoPath)
        print(GoodsUtils.GetGoodsExhibitBgByQualityType(vo.quality))
        CfUtils.FillImage(self.ImgRareBg, GoodsUtils.GetFishBgByQualityType(vo.quality))
        CfUtils.SetUISwitchImage(self.ImgRare1, checkNumber(vo.quality))
    end

    local limitPlaceId = FishingUtils.GetFishGoodsLimitPlaceData(self._goodsId)
    KTool.SetActive(self.Limit, checkNumber(limitPlaceId) > 0)
    if (checkNumber(limitPlaceId) > 0) then
        local vo = FishingUtils.GetFishingPlaceVo(limitPlaceId)
        local err = localize("仅限_name_渔场使用", {_name_ = vo.name})
        CfUtils.FillText(self.Limit.transform:Find("Text"), err)
    end

    CfUtils.SetUISwitchText(self.TexTrestrict, self._isEquip and 1 or 2)

    local isBaseProp = FishingUtils.IsBaseProps(self._goodsId)
    --if not isBaseProp then
        local text = FishingUtils.GetFishingGoodsShowNumText(self._goodsId)
        CfUtils.FillText(self.Limited.transform:Find("TextNumber"), text)
    --end

    KTool.SetActive(self.Unlimited, false)--isBaseProp)
    KTool.SetActive(self.Limited, true)--not isBaseProp)

    vo = FishingUtils.GetFishingGoodsVoById(self._goodsId)
    --是装备了的
    if self._isEquip then
        local type = GoodsUtils.GetIdType(self._goodsId)
        if type == Constants.IDType.GoodsReel or type == Constants.IDType.GoodsFishingRod then
            local isCanFix = FishingUtils.IsCanFixGoods(vo.id)
            KTool.SetActive(self.FontStyleButton, isCanFix)
            KTool.SetActive(self.CommonBtnConsumePop, isCanFix)

            self.FontStyleButton:ResetFontStyle("B7", localize("维修"))
            CfUtils.FillText(self.FontStyleButton.transform:Find("Text"), localize("维修"))
            SetButtonAction(self.FontStyleButton, Bind(self, self.OnBtnFix))
            local consumeNum = FishingUtils.GetFixConsumeNum(self._goodsId)
            CfUtils.FillCommonBtnConsumePopNode(self.CommonBtnConsumePop, vo.fixCurrency, consumeNum)
        elseif type == Constants.IDType.GoodsBait or type == Constants.IDType.GoodsFishingLine then
            self.FontStyleButton:ResetFontStyle("B7", localize("购买"))
            CfUtils.FillText(self.FontStyleButton.transform:Find("Text"), localize("购买"))

            KTool.SetActive(self.FontStyleButton, checkNumber(vo.isStoreGood) == 1)
            KTool.SetActive(self.CommonBtnConsumePop, checkNumber(vo.isStoreGood) == 1)
            if checkNumber(vo.isStoreGood) == 1 then
                SetButtonAction(self.FontStyleButton, Bind(self, self.OnBtnBuy))
                CfUtils.FillCommonBtnConsumePopNode(self.CommonBtnConsumePop, vo.currency, vo.price)
            end
        end

    else
        KTool.SetActive(self.StatusEmpty, false)
        local isUnlock = FishingUtils.isUnlockGoods(self._goodsId)

        if isUnlock then 
            CfUtils.RefeshGoodGo(self.GoodNode, self._goodsId, nil, 0.8, nil, function()
                if self._cb then
                    self._cb()
                end
            end)

            local isHave = FishingUtils.IsHaveFishingGoodsDojo(self._goodsId)
            --拥有的时候就是装备
            if isHave then
                self.FontStyleButton:ResetFontStyle("B7", localize("装备"))
                CfUtils.FillText(self.FontStyleButton.transform:Find("Text"), localize("装备"))
                SetButtonAction(self.FontStyleButton, Bind(self, self.OnBtnEquip))
                KTool.SetActive(self.CommonBtnConsumePop, false)
            else
                self.FontStyleButton:ResetFontStyle("B7", localize("购买并装备"))
                CfUtils.FillText(self.FontStyleButton.transform:Find("Text"), localize("购买并装备"))
                KTool.SetActive(self.FontStyleButton, checkNumber(vo.isStoreGood) == 1)
                KTool.SetActive(self.CommonBtnConsumePop, checkNumber(vo.isStoreGood) == 1)
                if checkNumber(vo.isStoreGood) == 1 then
                    SetButtonAction(self.FontStyleButton, Bind(self, self.OnBtnBuy))
                    CfUtils.FillCommonBtnConsumePopNode(self.CommonBtnConsumePop, vo.currency, vo.price)
                end

                --local curLevel, exp = FishingUtils.GetCurLevelAndExp()
                ----未解锁
                --if checkNumber(vo.needLevel) > checkNumber(curLevel) then
                --    CfUtils.FillText(self.TexTrestrict, localize("钓鱼等级_num_解锁", {_num_ = checkNumber(vo.needLevel)}))
                --    self.FontStyleButton:ResetFontStyle("B7", localize("购买"))   
                --end
            end
        else
            local placeVo = FishingUtils.GetFishingPlaceVo(vo.needLevel)
            if not placeVo then
                printError(string.format('--->>>查不找鱼场配置 %s %s', vo.needLevel, vo.id))
            else
                local err = localize("钓场_num_解锁", {_num_ = placeVo.name})
                CfUtils.FillText(self.TextLock, err)
            end
        end

        --事件传过来保持不动
        if isEvent then

        else
            KTool.SetActive(self.StatusLock, not isUnlock)
            KTool.SetActive(self.StatusContent, isUnlock)
        end
    end
end

--绘制加成属性
function UIFishPoolStoreBackPackGoodsInfoNode:FillAdditions(vo)
    local t = FishingUtils.GetAdditionDataByVo(vo)
    if not t then
        return
    end
    for k, v in pairs(t) do
        local go = self.Layout.transform:Find("Text"..k)
        if not go then
            go = CfUtils.InstantiateGo(self.Text, self.Layout)
            go.name = "Text"..k
        end

        CfUtils.FillText(go, FishingUtils.GetAdditionDesc(v))
    end
end

--装备
function UIFishPoolStoreBackPackGoodsInfoNode:OnBtnEquip()
    print(self._placeId)
    fishingComponent:FishingEquipReq(self._goodsId, function(lastEquipId)
        GameUtils.Toast(localize("已成功装备"))
        if self._cb then
            self._cb(lastEquipId)
        end
        --CS.Engine.Lib.KCookie.Set("IsFixFish", 1)

        local type = GoodsUtils.GetIdType(self._goodsId)
        if type == Constants.IDType.GoodsReel then
            CriWareUtils.PlaySe(UISheets.SFX_Fishing.path, UISheets.SFX_Fishing.fishing_fit_wheel)
        elseif type == Constants.IDType.GoodsFishingRod then
            CriWareUtils.PlaySe(UISheets.SFX_Fishing.path, UISheets.SFX_Fishing.fishing_fit_rod)
        elseif type == Constants.IDType.GoodsBait then
            CriWareUtils.PlaySe(UISheets.SFX_Fishing.path, UISheets.SFX_Fishing.fishing_fit_bait)
        elseif type == Constants.IDType.GoodsFishingLine then
            CriWareUtils.PlaySe(UISheets.SFX_Fishing.path, UISheets.SFX_Fishing.fishing_fit_line)
        end
    end, self._placeId)
end

