function UIFishPoolStoreBackPackGoodsInfoNode:OnBtnBuy()
    --local isBasepProp = FishingUtils.IsBaseProps(self._goodsId)
    --if isBasepProp then
    --    GameUtils.Toast(localize("该物品无法购买"))
    --    return
    --end
    local vo = FishingUtils.GetFishingGoodsVoById(self._goodsId)
    if not vo then
        return
    end

    local isUnlock = FishingUtils.isUnlockGoods(self._goodsId)
    if not isUnlock then
        local placeVo = FishingUtils.GetFishingPlaceVo(vo.needLevel)
        if not placeVo then
            printError(string.format('--->>>查不找鱼场配置 %s %s', vo.needLevel, vo.id))
        else
            local err = localize("钓场_num_解锁", {_num_ = placeVo.name})
            CfUtils.FillText(self.TextLock, err)
        end
        return
    end
    --local curLevel, exp = FishingUtils.GetCurLevelAndExp()
    --if checkNumber(vo.needLevel) > checkNumber(curLevel) then
    --    GameUtils.Toast(localize("钓鱼等级_num_解锁", {_num_ = checkNumber(vo.needLevel)}))
    --    return 
    --end


    local num = vo.maxBuy
    local type = GoodsUtils.GetIdType(self._goodsId)
    if type == Constants.IDType.GoodsReel or type == Constants.IDType.GoodsFishingRod then
        num = 1
    end

    local t = {
        goodsId = self._goodsId,
        consumeGoodsId = vo.currency,
        remainTime = 0,
        consumeNum = vo.price,
        haveNum = FishingUtils.GetFishingGoodsNum(self._goodsId),
        maxBuyNum = num,
        buyCb = function(num)
            fishingComponent:FishingBuyReq(self._goodsId, num, function()
                self:OnBtnEquip()
            end)
        end,
    }
    UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonBuyItemDialog, parameters = t}, {
    })

    --fishingComponent:FishingBuyReq(self._goodsId, 1)
end

--维修
function UIFishPoolStoreBackPackGoodsInfoNode:OnBtnFix()
    if true then
        fishingComponent:FishingFixReq(self._goodsId, function()
            GameUtils.Toast(localize("维修成功"))
        end)
        return
    end

    local vo = FishingUtils.GetFishingGoodsVoById(self._goodsId)
    if not vo then
        return
    end
    --local consumeNum = vo.fixPrice
    local consumeNum = FishingUtils.GetFixConsumeNum(self._goodsId)
    vo = GoodsConfMgr:GetInstance():GetGoodsVoById(vo.fixCurrency)
    if not vo then
        return
    end

    GameUtils.SecondConfirm(localize("是否消耗_name_维修？", {_name_ = vo.name}), function()
        fishingComponent:FishingFixReq(self._goodsId)
    end, nil, "", 4, {{goodsId = vo.id, num = consumeNum}})
end

function UIFishPoolStoreBackPackGoodsInfoNode:OnDestroy()
    Events.RemoveListener(Constants.EventNames.EveryThingChangeEventName, self.__everythingChangeHandler)
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIFishPoolStoreBackPackGoodsInfoNode
